CREATE TABLE `cron_monitoring` (
  `cron` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `expression` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `start_window_seconds` int NOT NULL DEFAULT '300',
  `ping_window_seconds` int NOT NULL DEFAULT '300',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `created_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `service` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `endpoint` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `trigger_type` enum('nats','http') COLLATE utf8mb4_unicode_ci DEFAULT 'nats',
  `track_run` tinyint(1) NOT NULL DEFAULT '1',
  `http_method` enum('GET','POST','NONE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NONE',
  PRIMARY KEY (`cron`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

